import {holes,forecast,clock} from './pace.js';
import {pinehurstHoles,videoId,videoSource,videoTimeFor,positionOnHole,courseSource} from './pinehurst.js';
const safe=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
export function journeyRows(group,groups){const f=forecast(group,groups);return holes.map((target,i)=>{const h=i+1,a=f.arrivals.find(x=>x.hole===h);const passed=h<group.hole,current=h===group.hole;return {hole:h,target,passed,current,eta:passed?'Played':current?'Playing now':clock(a.at),etaLabel:passed?'ROUND PROGRESS':current?'ON THIS HOLE':'ESTIMATED ARRIVAL',exit:passed?null:clock(f.arrivals.find(x=>x.hole===h+1)?.at??f.finish),occupancy:groups.filter(g=>g.hole===h).length};});}
function paceState(g,groups){const delay=forecast(g,groups).delay;return {delay,cls:delay>10?'late':delay>5?'watch':'on',text:delay>5?`${delay}m behind`:'On pace'};}
export function holeTraffic(h,groups,selected){const present=groups.filter(g=>g.hole===h),target=holes[h-1];return `<div class="hole-position"><div class="position-label"><span>GROUP POSITIONS</span><small>SIMULATED · NOT GPS</small><button class="hole-traffic-link" data-hole="${h}" aria-label="View hole ${h} traffic">↗</button></div><div class="position-fairway"><span class="position-tee">TEE</span><svg viewBox="0 0 360 85" aria-hidden="true"><path d="M15 52 Q95 67 150 44 T345 30" stroke="#e1d7b8" stroke-width="44" fill="none" stroke-linecap="round"/><path d="M15 52 Q95 67 150 44 T345 30" stroke="#9bb47d" stroke-width="28" fill="none" stroke-linecap="round"/><path d="M15 52 Q95 67 150 44 T345 30" stroke="#cad6ab" stroke-width="1" fill="none" stroke-dasharray="3 5"/><ellipse cx="335" cy="32" rx="22" ry="19" fill="#c1d29d"/><path d="M335 35v-24l12 4 -12 5" stroke="#3d5c37" fill="#3d5c37"/></svg>${present.map((g,i)=>{const p=positionOnHole(g,target),s=paceState(g,groups);return `<button class="golf-group-pin ${s.cls} ${g.id===selected?'selected':''}" data-group="${g.id}" style="left:${8+p*84}%;top:${39+(i%3)*12}%" aria-label="${safe(g.name)}, ${Math.round(p*100)} percent through hole, simulated, ${s.text}"><span>${String(g.id).padStart(2,'0')}</span><i>${Array.from({length:g.players},()=>'<b></b>').join('')}</i></button>`;}).join('')}<span class="position-green">GREEN</span></div>${present.length?`<div class="position-groups">${present.map(g=>{const s=paceState(g,groups);return `<button data-group="${g.id}" class="position-row"><span class="group-position-id ${s.cls}">${String(g.id).padStart(2,'0')}</span><span><strong>${safe(g.name)}${g.id===selected?' <small>YOUR GROUP</small>':''}</strong><small>${g.players} players · ${g.inHole} min on hole</small></span><em class="${s.cls}">${s.text}</em><span>↗</span></button>`;}).join('')}</div>`:'<p class="no-groups">No groups on this hole in the simulation.</p>'}</div>`;}
export function journeyMarkup(group,groups){const rows=journeyRows(group,groups),f=forecast(group,groups);return `<section class="pine-intro"><div class="pine-title"><span class="journey-kicker">FAIRWAY FLOW / COURSE 002</span><h2>Pinehurst<span>No. 2.</span></h2><p>A drone’s-eye view. A ground-level understanding.<br>Follow all eighteen holes, and the rhythm of every round.</p><div class="pine-facts"><span>DONALD ROSS</span><span>PAR 70</span><span>7,588 YDS · U.S. OPEN TEES</span></div><a class="journey-start" href="#journey-hole-1">Scroll into the round <span>↓</span></a></div><div class="journey-round"><label for="journey-group">FOLLOW A GROUP</label><select id="journey-group">${groups.map(g=>`<option value="${g.id}" ${g.id===group.id?'selected':''}>${safe(g.name)}</option>`).join('')}</select><div><span>TEE TIME<strong>${clock(group.tee)}</strong></span><span>EST. FINISH<strong>${clock(f.finish)}</strong></span></div><p>Demo data · ${Math.min(18,group.hole-1)}/18 holes played</p><button class="journey-current" data-jump-hole="${Math.min(18,group.hole)}">Go to ${group.hole>18?'final hole':`your group · hole ${group.hole}`} ↗</button></div></section><div class="pine-demo-note"><span class="dot"></span><strong>PINEHURST NO. 2 DEMO</strong><span>Real course & footage. Simulated golfers, locations, pace targets and ETAs.</span></div><div class="journey-scroll pine-scroll"><div class="journey-visual pine-visual"><div class="drone-frame"><div class="drone-top"><span>THE HOLE-BY-HOLE FLYOVER</span><span id="drone-hole-indicator">01 / 18</span></div><div class="drone-media"><img id="hole-photo" src="${pinehurstHoles[0].image}" alt="Pinehurst No. 2 hole 1 aerial preview from SkyFox" width="300" height="202"><div id="drone-player"></div><div class="drone-cover" id="drone-cover"><span>▶</span><h3>See the real fairway.</h3><p>Enable Golf Digest’s YouTube flyover.<br>Scroll to move between holes.</p><button id="enable-drone" class="primary">Enable drone footage</button><small>YouTube loads on click · starts muted</small></div></div><div class="drone-controls"><span id="drone-status" role="status">Hole-specific aerial preview</span><button id="toggle-drone-sync" hidden>Pause scroll sync</button></div><div class="drone-cue"><div><span id="drone-title">HOLE 01</span><h3 id="drone-name">${pinehurstHoles[0].title}</h3></div><span id="drone-score">PAR 4 <i>·</i> 402 YDS</span></div><div class="journey-progress"><div></div></div><div class="drone-nav"><button data-prev-hole aria-label="Previous hole">←</button><label for="hole-jump">Jump to hole</label><select id="hole-jump">${rows.map(r=>`<option value="${r.hole}">${String(r.hole).padStart(2,'0')}</option>`).join('')}</select><button data-next-hole aria-label="Next hole">→</button></div><div class="media-credit"><a href="${videoSource}" target="_blank" rel="noopener">Flyover: Golf Digest ↗</a><a href="https://tours.skyfoxgolf.com/360/pinehurst-no-2/clubhouse" target="_blank" rel="noopener">Previews: SkyFox ↗</a></div><p class="drone-help">Footage unavailable? Use the hole previews and <a id="watch-hole" href="${videoSource}&t=91s" target="_blank" rel="noopener">watch this hole on YouTube ↗</a></p></div><div class="pine-legend"><span><b></b>On pace</span><span><b class="amber"></b>Watch pace</span><span><b class="red"></b>Behind</span><span>● = group · dots = golfers</span></div></div><div class="journey-story">${rows.map((r,i)=>{const h=pinehurstHoles[i];return `<article class="hole-chapter ${i===0?'is-active':''}" id="journey-hole-${r.hole}" data-chapter="${r.hole}" aria-labelledby="hole-title-${r.hole}"><div class="chapter-card"><div class="chapter-top"><span>${i<9?'THE FRONT NINE':'THE BACK NINE'}</span><span>${String(r.hole).padStart(2,'0')} / 18</span></div><div class="pine-hole-heading"><span class="chapter-number">${String(r.hole).padStart(2,'0')}</span><div><span class="hole-yardage">PAR ${h.par} <i>·</i> ${h.yards} YDS</span><h2 id="hole-title-${r.hole}">${h.title}</h2></div></div><div class="chapter-eta"><div><span>${r.etaLabel}</span><strong>${r.eta}</strong></div><span class="chapter-state ${r.passed?'passed':r.current?'current':''}">${r.passed?'✓ Played':r.current?'● Your group is here':'↗ Coming up'}</span></div><div class="chapter-stats"><span>DEMO PACE TARGET<strong>${r.target} <small>min</small></strong></span><span>${r.passed?'COURSE TRAFFIC':'EST. CLEAR HOLE'}<strong>${r.passed?`${r.occupancy} groups`:r.exit}</strong></span></div>${holeTraffic(r.hole,groups,group.id)}${r.passed?'<small class="chapter-note">Past arrival times were not recorded in this demo.</small>':''}${i<17?`<a class="chapter-next" href="#journey-hole-${r.hole+1}">On to hole ${r.hole+1} <span>↓</span></a>`:'<div class="journey-finish">⚑ &nbsp; Eighteen holes. One good walk.</div>'}</div></article>`;}).join('')}</div></div><section class="journey-end"><span class="journey-kicker">BACK AT THE CLUBHOUSE</span><h2>Less waiting.<br>More Pinehurst.</h2><p>Advance the simulation to move the groups and refresh their pace.</p><a href="#journey-hole-1" class="journey-start">Back to the first tee ↑</a><div class="pine-sources"><a href="${courseSource}" target="_blank" rel="noopener">Official course & scorecard ↗</a><a href="${videoSource}" target="_blank" rel="noopener">Every Hole at Pinehurst No. 2 · Golf Digest ↗</a><span>Independent concept demo. Not affiliated with Pinehurst, Golf Digest or SkyFox.</span></div></section>`;}
let youtubePromise,droneOptedIn=false;
function loadYouTube(){if(window.YT?.Player)return Promise.resolve(window.YT);if(youtubePromise)return youtubePromise;youtubePromise=new Promise((resolve,reject)=>{const old=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{old?.();resolve(window.YT);};const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.onerror=()=>{youtubePromise=null;reject(new Error('YouTube unavailable'));};document.head.append(script);setTimeout(()=>{if(!window.YT?.Player){youtubePromise=null;reject(new Error('YouTube timed out'));}},14000);});return youtubePromise;}
export function mountJourney(root){const chapters=[...root.querySelectorAll('[data-chapter]')];if(!chapters.length)return ()=>{};const reduced=matchMedia('(prefers-reduced-motion: reduce)');let frame=0,active=-1,disposed=false,player=null,ready=false,sync=true,progress=0,lastSeek=0,pendingTimer;
 const status=root.querySelector('#drone-status');
 function update(){frame=0;if(disposed)return;const mobile=matchMedia('(max-width: 760px)').matches,focus=innerHeight*(mobile?.64:.5);let index=0;for(let i=0;i<chapters.length;i++)if(chapters[i].getBoundingClientRect().top<=focus)index=i;
 const rect=chapters[index].getBoundingClientRect();progress=Math.max(0,Math.min(1,(focus-rect.top)/Math.max(1,rect.height)));const h=pinehurstHoles[index],changed=index!==active;
 root.querySelector('.journey-progress div').style.width=`${(index+progress)/18*100}%`;
 if(changed){active=index;chapters.forEach((c,i)=>c.classList.toggle('is-active',i===index));const img=root.querySelector('#hole-photo');img.src=h.image;img.alt=`Pinehurst No. 2 hole ${h.hole} aerial preview from SkyFox`;root.querySelector('#drone-hole-indicator').textContent=`${String(h.hole).padStart(2,'0')} / 18`;root.querySelector('#drone-title').textContent=`HOLE ${String(h.hole).padStart(2,'0')}`;root.querySelector('#drone-name').textContent=h.title;root.querySelector('#drone-score').textContent=`PAR ${h.par} · ${h.yards} YDS`;root.querySelector('#hole-jump').value=h.hole;root.querySelector('#watch-hole').href=`${videoSource}&t=${Math.floor(h.start)}s`;root.querySelector('[data-prev-hole]').disabled=index===0;root.querySelector('[data-next-hole]').disabled=index===17;}
 if(ready&&sync){const now=performance.now();if(changed||now-lastSeek>450){const target=reduced.matches?h.start:videoTimeFor(h.hole,progress);if(changed||Math.abs(player.getCurrentTime()-target)>2){player.seekTo(target,true);lastSeek=now;}status.textContent=`Scroll-synced · hole ${h.hole}`;}}
 }
 function schedule(){if(!frame)frame=requestAnimationFrame(update);}
 function scrollToHole(h){const target=root.querySelector(`#journey-hole-${h}`);if(target){target.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'});target.focus({preventScroll:true});}}
 function failure(message){if(disposed)return;ready=false;root.querySelector('#drone-cover').hidden=false;root.querySelector('#enable-drone').disabled=false;root.querySelector('#enable-drone').textContent='Retry drone footage';root.querySelector('#toggle-drone-sync').hidden=true;status.textContent=message;}
 async function enable(){droneOptedIn=true;const button=root.querySelector('#enable-drone');button.disabled=true;button.textContent='Loading footage…';status.textContent='Connecting to YouTube…';try{const YT=await loadYouTube();if(disposed)return;player?.destroy();player=new YT.Player('drone-player',{videoId,playerVars:{playsinline:1,controls:1,rel:0,origin:location.origin,start:Math.floor(pinehurstHoles[Math.max(0,active)].start)},events:{onReady(){if(disposed)return;ready=true;clearTimeout(pendingTimer);player.mute();player.seekTo(pinehurstHoles[Math.max(0,active)].start,true);if(!reduced.matches)player.playVideo();root.querySelector('#drone-cover').hidden=true;root.querySelector('#toggle-drone-sync').hidden=false;schedule();},onError(){failure('YouTube playback unavailable. Use the preview or source link.');},onStateChange(e){if(e.data===0&&sync)schedule();}}});pendingTimer=setTimeout(()=>{if(!ready)failure('Video connection timed out. Preview mode is available.');},16000);}catch{failure('YouTube could not load. Preview mode is available.');}}
 function click(e){const anchor=e.target.closest('a[href^="#journey-hole-"]'),button=e.target.closest('button');if(anchor){e.preventDefault();scrollToHole(+anchor.getAttribute('href').split('-').pop());}if(!button)return;if(button.dataset.jumpHole)scrollToHole(+button.dataset.jumpHole);if(button.hasAttribute('data-prev-hole'))scrollToHole(Math.max(1,active));if(button.hasAttribute('data-next-hole'))scrollToHole(Math.min(18,active+2));if(button.id==='enable-drone')enable();if(button.id==='toggle-drone-sync'){sync=!sync;button.textContent=sync?'Pause scroll sync':'Resume scroll sync';status.textContent=sync?'Scroll sync enabled':'Free playback · scroll sync paused';if(sync)schedule();}}
 function change(e){if(e.target.id==='hole-jump')scrollToHole(+e.target.value);}
 const timer=setInterval(()=>{if(ready&&sync&&!disposed){const h=pinehurstHoles[Math.max(0,active)];if(player.getCurrentTime()>h.end-0.5){player.pauseVideo();player.seekTo(h.end-1,true);}}},600);
 chapters.forEach(c=>c.tabIndex=-1);root.addEventListener('click',click);root.addEventListener('change',change);window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);reduced.addEventListener('change',schedule);update();if(droneOptedIn)enable();
 return ()=>{disposed=true;cancelAnimationFrame(frame);clearInterval(timer);clearTimeout(pendingTimer);player?.destroy();root.removeEventListener('click',click);root.removeEventListener('change',change);window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule);reduced.removeEventListener('change',schedule);};
}
